<section class="order-help-panel"><h2>Order updates</h2>
@if($order->last_payment_failure_at && $order->status==='awaiting_payment')<p>A payment attempt was unsuccessful. You can retry using Pay securely above. Your order is confirmed only after payment verification.</p>@endif
@if(in_array($order->status,['expired','cancelled','refunded']))<p>{{ $order->status==='expired'?'The unpaid payment window has closed. Reserved stock has been released.':($order->status==='refunded'?'The payment provider has confirmed your full refund. Your bank may take additional time to reflect the credit.':'This order is cancelled and will not be dispatched.') }}</p>@endif
@if($orderRefund)<p><strong>Full refund:</strong> {{ $orderRefund->status==='processed'?'Processed by payment provider':($orderRefund->status==='demo'?'Preview only — no money moved':str_replace('_',' ',$orderRefund->status)) }} · {{ mz_money($orderRefund->amount) }}</p>@if($orderRefund->provider_id)<p>Refund reference: {{ $orderRefund->provider_id }}</p>@endif<p>We email you when the provider confirms a refund update. Contact support if you need help.</p>@endif
@foreach($orderRequests as $change)<article class="order-request-summary"><h3>{{ $change->kind==='cancel'?'Cancellation':'Return' }} request · {{ ucfirst($change->status) }}</h3><p>{{ $change->reason }}</p>@if($change->response)<p><strong>Team update:</strong> {{ $change->response }}</p>@endif</article>@endforeach
@php $canCancel=in_array($order->status,['awaiting_payment','paid','processing'])&&!$orderRequests->contains('kind','cancel');$canReturn=$order->status==='delivered'&&!$orderRequests->contains('kind','return'); @endphp
@if($canCancel || $canReturn)<details class="order-request-form"><summary>{{ $canCancel?'Cancel this order':'Request a return' }}</summary><form method="post" action="/orders/{{ $order->token }}/request">@csrf<input type="hidden" name="kind" value="{{ $canCancel?'cancel':'return' }}"><label>Reason<textarea name="reason" required minlength="5" maxlength="1000" rows="3" placeholder="Tell us briefly how we can help."></textarea></label><p class="small-copy">{{ $canCancel?'Unpaid cancellations are checked against payment status first. Paid cancellations need team approval before dispatch.':'Returns are reviewed under our return policy. Wait for approval and instructions before sending items back.' }} <a href="/pages/returns">Read the policy</a>.</p><button class="button button-outline">{{ $canCancel?'Request cancellation':'Send return request' }}</button></form></details>@endif
<a class="text-link" href="/pages/contact">Need help with this order?</a>
